'use client'
import { createContext, useContext, useState, useEffect } from 'react';
import { loginUser, signUpUser, logoutUser, getProfile, googleLogin, appleLogin } from '../lib/api';
import { GoogleOAuthProvider } from '@react-oauth/google';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check for stored auth token and validate
    checkAuthStatus();
  }, []);

  const checkAuthStatus = async () => {
    try {
      // Try to fetch profile. If it succeeds, we are logged in (via cookie)
      const userData = await getProfile();
      setUser(userData);
    } catch (error) {
      // If 401, it just means user is not logged in, which is expected on initial load
      if (error.status !== 401 && error.response?.status !== 401) {
        console.error('Auth check failed:', error);
      }
      setUser(null);
    } finally {
      setLoading(false);
    }
  };

  const login = async (email, password) => {
    try {
      await loginUser(email, password);
      // Backend sets HttpOnly cookies automatically
      const userData = await getProfile();
      setUser(userData);
      return { success: true };
    } catch (error) {
      console.error('Login failed:', error);
      return { success: false, error: error.message };
    }
  };

  const register = async (username, email, password) => {
    try {
      await signUpUser(username, email, password);
      // Backend sets HttpOnly cookies automatically
      const userData = await getProfile();
      setUser(userData);
      return { success: true };
    } catch (error) {
      console.error('Registration failed:', error);
      return { success: false, error: error.message };
    }
  };

  const loginWithGoogle = async (idToken) => {
    try {
      await googleLogin(idToken);
      const userData = await getProfile();
      setUser(userData);
      return { success: true };
    } catch (error) {
      console.error('Google login failed:', error);
      return { success: false, error: error.message };
    }
  };

  const loginWithApple = async (data) => {
    try {
      await appleLogin(data);
      const userData = await getProfile();
      setUser(userData);
      return { success: true };
    } catch (error) {
      console.error('Apple login failed:', error);
      return { success: false, error: error.message };
    }
  };

  const logout = async () => {
    try {
      await logoutUser();
      setUser(null);
    } catch (error) {
      console.error('Logout failed:', error);
      setUser(null);
      window.location.href = '/';
    }
  };

  return (
    <GoogleOAuthProvider clientId={process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID || ''}>
      <AuthContext.Provider value={{ user, loading, login, logout, register, checkAuthStatus, loginWithGoogle, loginWithApple }}>
        {children}
      </AuthContext.Provider>
    </GoogleOAuthProvider>
  );
}

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};